import{describe,it,expect}from"vitest";import{bordersData,getBorderById,filterBorders,getBordersByLength,getTotalBorderLength,getAllBorderForces,getAllBorderingStates,compareBorders}from"../../frontend/border-explorer/border-explorer.js";const MANDATORY_COUNTRIES=["Pakistan","China","Nepal","Bhutan","Bangladesh","Myanmar","Sri Lanka"];describe("Border Explorer Dataset Coverage",()=>{it("contains all 7 neighboring countries",()=>{expect(bordersData.length).toBe(7);const e=bordersData.map(e=>e.country);MANDATORY_COUNTRIES.forEach(t=>{expect(e).toContain(t)})}),it("every border record has all required fields",()=>{bordersData.forEach((e,t)=>{expect(e,`Item ${t} missing id`).toHaveProperty("id"),expect(e,`Item ${t} missing country`).toHaveProperty("country"),expect(e,`Item ${t} missing borderName`).toHaveProperty("borderName"),expect(e,`Item ${t} missing borderLength`).toHaveProperty("borderLength"),expect(e,`Item ${t} missing borderForce`).toHaveProperty("borderForce"),expect(e,`Item ${t} missing majorCheckpoints`).toHaveProperty("majorCheckpoints"),expect(e,`Item ${t} missing importantTowns`).toHaveProperty("importantTowns"),expect(e,`Item ${t} missing borderingStates`).toHaveProperty("borderingStates"),expect(e,`Item ${t} missing description`).toHaveProperty("description"),expect(e,`Item ${t} missing geographicFeatures`).toHaveProperty("geographicFeatures"),expect(typeof e.borderLength).toBe("number"),expect(e.borderLength).toBeGreaterThan(0),expect(Array.isArray(e.majorCheckpoints)).toBe(!0),expect(e.majorCheckpoints.length).toBeGreaterThanOrEqual(1),expect(Array.isArray(e.importantTowns)).toBe(!0),expect(e.importantTowns.length).toBeGreaterThanOrEqual(1),expect(Array.isArray(e.borderingStates)).toBe(!0),expect(e.borderingStates.length).toBeGreaterThanOrEqual(1)})}),it("every checkpoint has name, state, type, and description",()=>{bordersData.forEach(e=>{e.majorCheckpoints.forEach((t,r)=>{expect(t,`Checkpoint ${r} of ${e.country} missing name`).toHaveProperty("name"),expect(t,`Checkpoint ${r} of ${e.country} missing state`).toHaveProperty("state"),expect(t,`Checkpoint ${r} of ${e.country} missing type`).toHaveProperty("type"),expect(t,`Checkpoint ${r} of ${e.country} missing description`).toHaveProperty("description")})})}),it("all border IDs are unique",()=>{const e=bordersData.map(e=>e.id);expect(new Set(e).size).toBe(e.length)})}),describe("Border Length Aggregation & Sorting",()=>{it("calculates total border length correctly",()=>{const e=getTotalBorderLength(),t=bordersData.reduce((e,t)=>e+t.borderLength,0);expect(e).toBe(t),expect(e).toBeGreaterThan(14e3)}),it("sorts borders by length descending",()=>{const e=getBordersByLength();expect(e.length).toBe(bordersData.length);for(let t=0;t<e.length-1;t++)expect(e[t].borderLength).toBeGreaterThanOrEqual(e[t+1].borderLength);expect(e[0].country).toBe("Bangladesh")})}),describe("Border Forces & Bordering States",()=>{it("returns all unique border forces",()=>{const e=getAllBorderForces();expect(e.length).toBeGreaterThanOrEqual(4),expect(e).toContain("Border Security Force (BSF)"),expect(e).toContain("Indo-Tibetan Border Police (ITBP)"),expect(e).toContain("Sashastra Seema Bal (SSB)"),expect(e).toContain("Assam Rifles")}),it("returns all unique bordering states",()=>{const e=getAllBorderingStates();expect(e.length).toBeGreaterThanOrEqual(10)})}),describe("Search & Filter Functions",()=>{it("retrieves border by ID",()=>{const e=getBorderById("india-pakistan");expect(e).toBeDefined(),expect(e.country).toBe("Pakistan")}),it("retrieves border by country name",()=>{const e=getBorderById("Nepal");expect(e).toBeDefined(),expect(e.borderName).toContain("Open Border")}),it("filters by search query matching checkpoint names",()=>{const e=filterBorders("Wagah");expect(e.length).toBe(1),expect(e[0].country).toBe("Pakistan")}),it("filters by search query matching bordering state",()=>{const e=filterBorders("Sikkim");expect(e.length).toBeGreaterThanOrEqual(2)}),it("returns all when query is empty",()=>{const e=filterBorders("");expect(e.length).toBe(7)}),it("returns empty array when query matches nothing",()=>{const e=filterBorders("NonExistentXYZ123");expect(e).toEqual([])})}),describe("Country Comparison Engine",()=>{it("compares two borders and returns correct structure",()=>{const e=compareBorders("india-pakistan","india-china");expect(e).not.toBeNull(),expect(e.countries).toEqual(["Pakistan","China"]),expect(e.borderLengths[0]).toBe(3323),expect(e.borderLengths[1]).toBe(3488),expect(e.longerBorder).toBe("China"),expect(e.borderForces.length).toBe(2)}),it("returns null when an invalid ID is given",()=>{const e=compareBorders("india-pakistan","nonexistent");expect(e).toBeNull()})});